const { randomUUID } = require('node:crypto');
const express = require('express');
const helmet = require('helmet');
const pinoHttp = require('pino-http');

/**
 * Express app with the middleware every service needs: security headers,
 * request-id propagation, structured request logging, JSON body parsing and
 * a /health endpoint. Services mount their own routers on top of it.
 */
function createBaseApp({ logger, healthCheck }) {
  const app = express();

  app.disable('x-powered-by');
  app.use(helmet());
  app.use(
    pinoHttp({
      logger,
      // Reuse the id generated by the gateway so one request can be traced across services
      genReqId: (req, res) => {
        const id = req.headers['x-request-id'] || randomUUID();
        res.setHeader('x-request-id', id);
        return id;
      },
      autoLogging: { ignore: (req) => req.url === '/health' },
    }),
  );
  app.use(express.json({ limit: '1mb' }));

  app.get('/health', async (_req, res) => {
    try {
      if (healthCheck) await healthCheck();
      res.json({ status: 'ok', uptime: process.uptime() });
    } catch (err) {
      res.status(503).json({ status: 'unavailable', error: err.message });
    }
  });

  return app;
}

module.exports = { createBaseApp };
